import 'dart:collection';

class Transaction {
  final String coinName;
  final DateTime dateTime;
  final double profitLoss; // Positive for profit, negative for loss

  Transaction({required this.coinName, required this.dateTime, required this.profitLoss});
}

Future<Map<String, dynamic>> analyzeTransactions(List<Transaction> transactions) async {
  // Group transactions by coin name for calculating averages
  final groupedTransactions = transactions.groupBy((txn) => txn.coinName);

  // Calculate average profit/loss per coin
  final coinAverages = <String, double>{};
  for (var (coin, txnList) in groupedTransactions.entries) {
    double totalProfitLoss = txnList.fold(0, (sum, txn) => sum + txn.profitLoss);
    coinAverages[coin] = totalProfitLoss / txnList.length;
  }

  // Sort coins by average profit (descending) and loss (ascending)
  final sortedProfits = coinAverages.entries.toList()
    ..sort((a, b) => b.value.compareTo(a.value)); // Highest profit first
  final sortedLosses = coinAverages.entries.toList()
    ..sort((a, b) => a.value.compareTo(b.value)); // Lowest loss (highest negative) first

  return {
    'topProfits': sortedProfits.sublist(0, 3).map((entry) => entry.key).toList(),
    'topLosses': sortedLosses.sublist(0, 3).map((entry) => entry.key).toList(),
  };
}
```

