const slackApiCall = async (text, channelId) => {
  // **1. Setup & Authentication (Verbosity: High for clarity)**
  const SLACK_API_TOKEN = process.env.SLACK_BOT_TOKEN; //  ** Crucial: Replace with your actual Slack Bot Token **
  if (!SLACK_API_TOKEN) {
    console.error("ERROR: Environment variable SLACK_BOT_TOKEN not set. Slack posting disabled.");
    return; // Halt execution, prioritize helpfulness by indicating error
  }

  const slackWebhookUrl = `https://slack.com/api/chat.postMessage`; // Base Slack API URL

  // 2. Construct Payload (Structured for API Request - Helpfulness: High)
  const payload = {
    token: SLACK_API_TOKEN,
    channel: channelId, // Channel ID to post in
    text: text,
    // Optional enhancements for richer messages (verbosity & helpfulness):
    //   "blocks": structuredMessageBlocks, // For formatted Slack blocks (docs: https://api.slack.com/reference/block-kit)
    //   "attachments": [{...}] //  For media, fields, etc.
  };

  // 3. API Call with Fetch (Robust & Common Practice)
  try {
    const response = await fetch(slackWebhookUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    });
    const data = await response.json();

    if (response.ok) { // Successful API interaction
      console.log(`Message posted to #${channelId} successfully!`); 
      // Helpful feedback & logging
    } else {
      console.error(`Slack API Error: ${data.error}`, data); // Detailed error handling
    }
  } catch (error) {
    console.error("Network or API Error during posting:", error);
  }
};

// **Usage Example:**
slackApiCall("Hello from my JavaScript function!", "YOUR_CHANNEL_ID"); 
