using namespace std;

// Recursive Fibonacci function
int fibonacci(int a, int b, int n) {
    if (n == 0) return a;  // Base case: 0th element is the first input 'a'
    if (n == 1) return b;  // Base case: 1st element is the second input 'b'
    return fibonacci(b, a + b, n - 1); // Recursive step
}

int main() {
    int start1, start2, count;

    // Input and Validation Loop
    do {
        cout << "Enter the first two Fibonacci numbers: ";
        if (!(cin >> start1 >> start2)) {  // Error handling for non-numeric input
            cin.clear();
            cin.ignore(numeric_limits<streamsize>::max(), '\n');
            cerr << "Invalid input. Please enter integers.\n";
        } else if (start1 < 0 || start2 < 0) {  // Handle negative numbers
            cerr << "Invalid input: Both starting numbers must be non-negative.\n";
        } else {
            break;  // Valid input obtained
        }
    } while (true);

    do {
        cout << "Enter the desired number of Fibonacci elements to generate: ";
        if (!(cin >> count) || count <= 0) {  // Validate count input
            cin.clear();
            cin.ignore(numeric_limits<streamsize>::max(), '\n');
            cerr << "Invalid input. Please enter a positive integer.\n";
        } else {
            break;
        }
    } while (true);

    // Generate and Output Sequence
