namespace RestServiceWrapper
{
    public class GenericRestService<T> where T : class
    {
        private readonly HttpClient _httpClient;
        private readonly string _baseUrl;
        private string _authToken;

        public GenericRestService(string baseUrl, string initialAuthToken = null)
        {
            _baseUrl = baseUrl;
            _authToken = initialAuthToken;
            _httpClient = new HttpClient { BaseAddress = new Uri(_baseUrl) };
            // Add optional middleware for automatic header management (see enhancement below)
        }

        /// <summary>
        /// Sets a new authentication token for subsequent requests.
        /// </summary>
        public void SetAuthToken(string token) => _authToken = token;

        /// <summary>
        ///  Generic GET request with auth token handling.
        /// </summary>
        public async Task<T> GetAsync(string apiEndpoint, object queryParameters = null)
        {
            var url = BuildUrl(apiEndpoint, queryParameters);
            return await MakeRequestWithAuth<T>(HttpMethod.Get, url, null);
        }

        /// <summary>
        /// Generic POST request with data and auth token handling.
        /// </summary>
        public async Task<T> PostAsync(string apiEndpoint, object data, object queryParameters = null)
        {
            var url = BuildUrl(apiEndpoint, queryParameters);
            var content = JsonConvert.SerializeObject(data);
            return await MakeRequestWithAuth<T>(HttpMethod.Post, url, content);
        }

        /// <summary>
        ///  (Similarly implement PUT, DELETE, PATCH as needed) ... </summary>

        private async Task<T> MakeRequestWithAuth<T>(HttpMethod method, string url, string content = null)
